                phase := 1;
                conveyorRight := TRUE;
            ELSIF targetStation < currentStation THEN
                phase := 1;
                conveyorLeft := TRUE;
            ELSE
                phase := 2;
            END_IF;
        END_IF;

    1:
        arrived := FALSE;
        CASE targetStation OF
            1: arrived := sensor1;
            2: arrived := sensor2;
            3: arrived := sensor3;
            4: arrived := sensor4;
            5: arrived := sensor5;
        ELSE
            arrived := FALSE;
        END_CASE;

        IF arrived THEN
            currentStation := targetStation;
            IF targetStation = 5 THEN
                phase := 0;
            ELSE
                phase := 2;
            END_IF;
        ELSE
