                conveyorRight := TRUE;
                conveyorLeft := FALSE;
            ELSIF targetStation < currentStation THEN
                conveyorLeft := TRUE;
                conveyorRight := FALSE;
            ELSE
                conveyorLeft := FALSE;
                conveyorRight := FALSE;
